// Cache track metadata in Redis
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

const track = $input.item.json;

const cacheKey = `track:${track.track_id}`;
const cacheData = {
  track_id: track.track_id,
  track_name: track.track_name,
  artists: track.artists,
  album_name: track.album_name,
  album_art_url: track.album_art_url,
  duration_ms: track.duration_ms
};

await redis.setex(cacheKey, 86400, JSON.stringify(cacheData));

return { json: track };

// Publish to WebSocket via Redis Pub/Sub
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

const activity = $input.item.json;

// Get user's friends from database
const { Client } = require('pg');
const client = new Client({ connectionString: process.env.DATABASE_URL });
await client.connect();

const result = await client.query(
  `SELECT friend_id FROM friendships 
   WHERE user_id = $1 AND status = 'accepted'`,
  [activity.user_id]
);

const friends = result.rows.map(r => r.friend_id);
await client.end();

// Publish to Redis
await redis.publish('feed-updates', JSON.stringify({
  targetUsers: friends,
  payload: {
    type: 'feed:new-activity',
    userId: activity.user_id,
    activity: activity,
    timestamp: Date.now()
  }
}));

return { json: { published: true, friendCount: friends.length } };

// Check for shared songs with friends
const { Client } = require('pg');
const client = new Client({ connectionString: process.env.DATABASE_URL });
await client.connect();

const activity = $input.item.json;

// Find friends who also listened to this track
const result = await client.query(
  `SELECT DISTINCT la.user_id
   FROM listening_activity la
   JOIN friendships f ON (
     (f.user_id = $1 AND f.friend_id = la.user_id) OR
     (f.friend_id = $1 AND f.user_id = la.user_id)
   )
   WHERE la.track_id = $2 
   AND la.user_id != $1
   AND f.status = 'accepted'
   AND la.played_at >= NOW() - INTERVAL '7 days'`,
  [activity.user_id, activity.track_id]
);

const sharedWith = result.rows;

// Create shared song records
for (const friend of sharedWith) {
  await client.query(
    `INSERT INTO shared_songs (
       user1_id, user2_id, track_id, track_name, artists, 
       discovery_type, last_updated_at
     )
     VALUES ($1, $2, $3, $4, $5, 'exact_match', NOW())
     ON CONFLICT (user1_id, user2_id, track_id, discovery_type)
     DO UPDATE SET 
       user1_play_count = shared_songs.user1_play_count + 1,
       last_updated_at = NOW()`,
    [activity.user_id, friend.user_id, activity.track_id, 
     activity.track_name, activity.artists]
  );
}

await client.end();

return { json: { sharedWith: sharedWith.length } };
